package com.mygo.music;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import org.json.*;
import java.io.*;
import java.util.*;
/** Two instrumentation processes separated by a real am force-stop, with scoped state restoration. */
final class ThemeRestartChecks {
 static final String[] KEYS={"player_theme","player_default_theme","player_remember_theme","theme_glass_background_mode","theme_glass_blur","theme_glass_opacity","theme_glass_brightness","theme_glass_low_performance"};
 final Instrumentation test;final Context context;final SharedPreferences prefs;final File backup,photoBackup;
 ThemeRestartChecks(Instrumentation test){this.test=test;context=test.getTargetContext();prefs=context.getSharedPreferences("library",0);backup=new File(context.getCacheDir(),"theme-restart-state.json");photoBackup=new File(context.getCacheDir(),"theme-restart-original.jpg");}
 void prepare()throws Exception{if(backup.exists())throw new AssertionError("restart probe already has unrestored state");JSONObject state=new JSONObject(),values=new JSONObject();Map<String,?> all=prefs.getAll();for(String key:KEYS)if(all.containsKey(key))values.put(key,all.get(key));state.put("values",values);File original=ThemeBackdrop.photo(context,"glass");state.put("photo",original.exists());if(original.exists()&&!original.renameTo(photoBackup))throw new IOException("cannot preserve original theme photo");try(FileOutputStream out=new FileOutputStream(backup)){out.write(state.toString().getBytes("UTF-8"));out.getFD().sync();}Bitmap image=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);image.eraseColor(0xff38758d);File input=new File(context.getCacheDir(),"theme-restart-input.png");try(FileOutputStream out=new FileOutputStream(input)){image.compress(Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}try{ThemeBackdrop.importPhoto(context,Uri.fromFile(input),"glass");prefs.edit().putString("player_theme","glass").putString("player_default_theme","minimal").putBoolean("player_remember_theme",true).putInt("theme_glass_blur",61).putInt("theme_glass_opacity",73).putInt("theme_glass_brightness",88).putBoolean("theme_glass_low_performance",true).commit();}finally{input.delete();}}
 void verify()throws Exception{NowPlayingChecks actions=new NowPlayingChecks(test);MainActivity activity=null;ThemedPlayerDialog[] page={null};try{if(!backup.isFile())throw new AssertionError("restart prepare state missing");NowPlayingChecks.check(PlayerThemes.current(prefs).equals("glass")&&prefs.getInt("theme_glass_blur",0)==61&&prefs.getInt("theme_glass_opacity",0)==73&&prefs.getInt("theme_glass_brightness",0)==88&&prefs.getBoolean("theme_glass_low_performance",false),"force-stop lost saved theme settings");NowPlayingChecks.check(ThemeBackdrop.photo(context,"glass").isFile(),"force-stop lost custom background");activity=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));MainActivity target=activity;actions.ui(()->{NowPlayingChecks.invoke(target,"showNowPlaying");page[0]=(ThemedPlayerDialog)FullPortChecks.field(target,"themedPlayer");});new CompletionChecks(test).await(()->page[0]!=null&&page[0].isShowing()&&page[0].theme().equals("glass")&&(Boolean)FullPortChecks.field(page[0],"lowPerformance")&&FullPortChecks.field(page[0].backdrop,"original")!=null,"new process did not reopen saved glass page and decode its photo");System.out.println("MYGO_THEME_RESTART_OK actualForceStop=true scene=glass blur=61 opacity=73 brightness=88 photoDecoded=true lowPerformance=true");}finally{MainActivity target=activity;actions.ui(()->{if(page[0]!=null)page[0].dismiss();if(target!=null)target.finish();});restore();}}
 private void restore()throws Exception{if(!backup.isFile())return;JSONObject state=new JSONObject(new String(java.nio.file.Files.readAllBytes(backup.toPath()),"UTF-8")),values=state.getJSONObject("values");SharedPreferences.Editor edit=prefs.edit();for(String key:KEYS){edit.remove(key);if(values.has(key)){Object value=values.get(key);if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);else if(value instanceof Number)edit.putInt(key,((Number)value).intValue());else edit.putString(key,(String)value);}}edit.commit();File original=ThemeBackdrop.photo(context,"glass");original.delete();if(state.optBoolean("photo")&&!photoBackup.renameTo(original))throw new IOException("cannot restore original photo");backup.delete();}
}
